function renderOceanPage(pageName, containerId) {
  const container = document.getElementById(containerId);
  if (!container) return;
  let html = oceanPages[pageName] || oceanPages["index.html"];
  
  // Inject dark purple animated CSS
  if (!document.getElementById("ocean-injected-css")) {
    const style = document.createElement("style");
    style.id = "ocean-injected-css";
    style.innerHTML = oceanCSS;
    document.head.appendChild(style);
  }
  
  container.innerHTML = html;
  
  // Initialize mouse glow and reveal animations
  if (!document.getElementById("ocean-mouse-glow")) {
    const glow = document.createElement("div");
    glow.id = "ocean-mouse-glow";
    glow.style.cssText = "position:fixed;inset:0;z-index:9999;pointer-events:none;mix-blend-mode:screen;opacity:0.35;background:radial-gradient(circle 300px at var(--mx,50%) var(--my,50%),rgba(184,75,255,0.35),transparent 70%);transition:background 0.08s ease-out;";
    document.body.appendChild(glow);
    document.addEventListener("mousemove", e => {
      glow.style.setProperty("--mx", e.clientX + "px");
      glow.style.setProperty("--my", e.clientY + "px");
    });
  }
}
